query GetShareCollectionAssets($shareId: ID!, $folderId: ID, $assetType: ChildAssetTypeInput, $page: PageInput!) {
  share(shareId: $shareId) {
    id
    ... on Share {
      collectionAssets(page: $page, assetType: $assetType, folderId: $folderId) {
        pageInfo {
          endCursor
          hasNextPage
          mode
          __typename
        }
        groups {
          ...GroupInfo
          __typename
        }
        nodes {
          id
          index
          group {
            id
            __typename
          }
          __typename
        }
        __typename
      }
      __typename
    }
    __typename
  }
}

fragment GroupInfo on CollectionAssetsGroup {
  id
  endCursor
  values {
    id
    value {
      ... on DerivedFieldValue {
        derived
        __typename
      }
      ... on JsonFieldValue {
        json
        __typename
      }
      ... on LinkFieldValue {
        link
        __typename
      }
      ... on LongTextFieldValue {
        longText
        __typename
      }
      ... on NumberFieldValue {
        number
        __typename
      }
      ... on RatingFieldValue {
        rating
        __typename
      }
      ... on SelectFieldValue {
        selectedOptions
        __typename
      }
      ... on SelectMultiFieldValue {
        multiSelectedOptions
        __typename
      }
      ... on TextFieldValue {
        text
        __typename
      }
      ... on ToggleFieldValue {
        toggle
        __typename
      }
      ... on UsersFieldValue {
        selectedMembers {
          id
          __typename
        }
        __typename
      }
      ... on UserSingleFieldValue {
        singleSelectedMember {
          id
          __typename
        }
        __typename
      }
      ... on DateFieldValue {
        date
        __typename
      }
      ... on UrlFieldValue {
        url
        __typename
      }
      __typename
    }
    __typename
  }
  __typename
}
